const writeReg=(x:RegFlow)=>sessionStorage.setItem(REG_KEY,JSON.stringify(x));
const deviceId=()=>{let x=localStorage.getItem(DEVICE_KEY);if(!x){x=crypto.randomUUID?crypto.randomUUID():"web-"+Date.now();localStorage.setItem(DEVICE_KEY,x)}return x};
const routePage=():Page|null=>{const p=window.location.pathname;if(/^\/policy\/[^/]+$/.test(p))return "policy";if(/^\/support\/cases\/R\d{11}$/i.test(p))return "support-case";const authRoutes:Record<string,Page>={"/app/login":"login-entry","/app/findAccount":"find-account","/app/deviceVerification":"device-verify","/app/loginTwoFactor":"two-factor","/app/registrationWelcome":"register-welcome","/app/registrationIdentity":"register-identity","/app/registrationBirthday":"register-birthday","/app/registrationGender":"register-gender","/app/registrationPhone":"register-phone","/app/registrationEmail":"register-email","/app/registrationPassword":"register-password","/app/registrationReview":"register-review","/app/registrationVerification":"register-verify","/app/customizingExperience":"customizing"};if(authRoutes[p])return authRoutes[p];if(p==="/app/resetCode")return "reset-code";if(p==="/app/resetPassword")return "reset-password";if(/^\/app(?:\/|$)/i.test(p))return "web-parity";return null};
const pagePath=(p:Page)=>({home:"/app/homeFeed","login-entry":"/app/login",login:"/app/login","recognized-accounts":"/app/login","recognized-password":"/app/login","manage-profiles":"/app/login","profile-detail":"/app/login","find-account":"/app/findAccount","reset-code":"/app/resetCode","reset-password":"/app/resetPassword","device-verify":"/app/deviceVerification","two-factor":"/app/loginTwoFactor","register-welcome":"/app/registrationWelcome","register-identity":"/app/registrationIdentity","register-birthday":"/app/registrationBirthday","register-gender":"/app/registrationGender","register-phone":"/app/registrationPhone","register-email":"/app/registrationEmail","register-password":"/app/registrationPassword","register-review":"/app/registrationReview","register-verify":"/app/registrationVerification",customizing:"/app/customizingExperience","oauth-consent":"/app/oauth/consent"} as Partial<Record<Page,string>>)[p];
const ageFrom=(v:string)=>{const d=new Date(v+"T00:00:00"),n=new Date();let a=n.getFullYear()-d.getFullYear();const m=n.getMonth()-d.getMonth();if(m<0||(m===0&&n.getDate()<d.getDate()))a--;return a};
const fmt=(s:number)=>Math.floor(s/60)+":"+String(s%60).padStart(2,"0");
function useTimer(until?:string){const[s,setS]=useState(until?Math.max(0,Math.ceil((new Date(until).getTime()-Date.now())/1000)):0);useEffect(()=>{if(!until)return;const f=()=>setS(Math.max(0,Math.ceil((new Date(until).getTime()-Date.now())/1000)));f();const t=setInterval(f,1000);return()=>clearInterval(t)},[until]);return s}
function Shell({children}:{children:any}){return <div className="auth-wrap"><div className="auth-card"><section className="auth-content">{children}<small className="auth-foot">ReDom Platforms, Inc.</small></section><aside className="auth-security-rail"><div className="auth-security-icon"><SvgAsset src={SecurityShieldSvg} className="auth-svg-icon" /></div><span className="eyebrow">REDOM SECURITY</span><h2>Protected from the foundation up.</h2><p>Every registration, login, recovery and sensitive account action is processed through the ReDom Backend security boundary.</p><div className="auth-security-list"><div><b>Network security</b><span>Connection checked before account access.</span></div><div><b>Device verification</b><span>New browsers and devices can require verification.</span></div><div><b>Session validation</b><span>Authenticated sessions are refreshed and invalidated when required.</span></div><div><b>Protected actions</b><span>Payment and security operations remain behind authenticated server checks.</span></div></div><div className="auth-security-status"><i/> Secure Web session</div></aside></div></div>}
function Field({label,value,onChange,type="text",placeholder=""}:{label:string;value:string;onChange:(v:string)=>void;type?:string;placeholder?:string}){return <label className="field"><span>{label}</span><input type={type} value={value} placeholder={placeholder} onChange={e=>onChange(e.target.value)}/></label>}
function ErrorBox({text}:{text:string}){return text?<div className="alert">{text}</div>:null}
function Primary({children,disabled,onClick}:{children:any;disabled?:boolean;onClick?:()=>void}){return <button className="btn primary xl full" disabled={disabled} onClick={onClick}>{children}</button>}
function Progress({step}:{step:number}){return <div className="stepbar">{Array.from({length:6},(_,i)=><i key={i} className={i<=step?"done":""}/>)}</div>}

function formatSecurityScore(value:any){const numeric=Number(value);return Number.isFinite(numeric)?numeric.toFixed(2)+"%":"0.00%";}
function maskIp(ip:unknown){if(typeof ip!=="string"||!ip.trim())return "Detecting…";const value=ip.trim();if(value.includes(":"))return value.slice(0,8)+"••••••";const parts=value.split(".");return parts.length===4?parts[0]+"."+parts[1]+".•••••":value.slice(0,6)+"•••••";}
function startupTitle(profile:any){return profile?.termsLabel||"ReDom Network Security Check";}
function startupWarning(profile:any){const s=profile?.security;if(!s)return null;if(s.vpn)return "VPN detected. Your current connection appears to be using a VPN provider.";if(s.datacenter)return "Datacenter connection detected. This connection appears to come from a hosting or cloud network.";if(s.proxy)return "Proxy detected. This connection appears to use a proxy.";if(s.tor)return "Tor detected. Please use your normal Internet connection to continue.";if(s.bot)return "Automated traffic detected. This connection was identified as automated traffic.";if(s.abuser||Number(s.fraudScore||0)>=75)return "High security risk detected. IPAPI assigned this connection a fraud-risk score of "+formatSecurityScore(s.fraudScore)+".";
return null;}
function Startup({done,setNetwork}:{done:()=>void;setNetwork:(x:NetworkProviderResponse)=>void}){const rotation=useRef(0);const[p,setP]=useState<NetworkProviderResponse|null>(null),[checking,setChecking]=useState(true),[securityOpen,setSecurityOpen]=useState(true),[completed,setCompleted]=useState(false);const run=async()=>{setChecking(true);setP(null);setSecurityOpen(true);const r=await startupNetworkCheck(api);setP(r);setNetwork(r);setChecking(false);setSecurityOpen(true)};useEffect(()=>{let live=true;(async()=>{const r=await startupNetworkCheck(api);if(!live)return;setP(r);setNetwork(r);setChecking(false);setSecurityOpen(true)})();return()=>{live=false}},[]);const security=p?.security;const warning=startupWarning(p);const failed=Boolean(p&&(!p.success||!security));const isVpnOrDatacenter=Boolean(security?.vpn||security?.datacenter);const termsTitle=startupTitle(p||{success:false,security:null});const continueToLogin=()=>{if(checking||failed||!security||completed)return;setSecurityOpen(false);setCompleted(true);done();};return <div className="startup-screen"><div className="startup-artwork-wrap"><SvgAsset src={StartupArtwork} className="startup-artwork"/><div className="startup-spinner-exact" style={{transform:"rotate("+(rotation.current)+"deg)"}}><i/></div></div>{securityOpen?<div className="startup-backdrop"><div className="startup-card-exact"><div className="startup-icon-circle"><SvgAsset src={WarningBlackSvg} className="startup-warning-icon"/></div><h1>{checking?"Checking Your Network":termsTitle}</h1><p>{checking?"ReDom is checking your current network before Login opens.":failed?(p?.warning||"ReDom could not complete the network security check."):p?.networkProvider?p.networkProvider+" connection detected.":"Your connection has been checked."}</p>{warning?<div className="startup-warning"><SvgAsset src={WarningBlackSvg} className="startup-warning-small"/><span>{warning}</span></div>:null}{security?<div className="startup-security-rows"><div><span>Your IP</span><b>{maskIp(security.ip)}</b></div><div><span>Connection</span><b>{security.connection||"Unknown"}</b></div><div><span>Provider</span><b>{p?.networkProvider||"Unknown"}</b></div><div><span>Location</span><b>{[security.city,security.region,security.country].filter(Boolean).join(", ")||"Unknown"}</b></div><div><span>Security score</span><b>{formatSecurityScore(security.fraudScore)}</b></div></div>:null}{isVpnOrDatacenter?<p className="startup-embedded-notice">Your connection type was detected automatically. ReDom is showing this warning before Login because the current network is not a normal residential/mobile connection.</p>:null}{!checking&&!failed&&p?.termsUrl?<button className="startup-terms" onClick={()=>window.open(p.termsUrl!,"_blank","noopener,noreferrer")}><b>{termsTitle}</b><small>{p.termsUrl}</small></button>:null}{checking?<button className="btn primary xl full startup-action" disabled><span className="startup-button-spinner"/>Checking network…</button>:failed?<button className="btn primary xl full startup-action" onClick={()=>void run()}>Retry Network Check</button>:<button className="btn primary xl full startup-action" onClick={continueToLogin}>OK, Continue</button>}</div></div>:null}</div>;}

