function OAuthConsent({go}:{go:(p:Page)=>void}){const[request,setRequest]=useState<any>(null),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState("");const id=oauthRequestId();useEffect(()=>{let live=true;if(!id){go("login");return}void api<any>("/oauth/request/"+encodeURIComponent(id)).then(r=>{if(live)setRequest(r)}).catch(e=>{if(live)setError(e instanceof Error?e.message:"Unable to load the authorization request.")}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[id,go]);const approve=async()=>{if(!id||busy)return;setBusy(true);setError("");try{const r=await api<any>("/oauth/request/"+encodeURIComponent(id)+"/approve",{method:"POST"});if(!r.success||!r.code||!r.redirectUri)throw new Error(r.message||"Unable to approve access.");const u=new URL(r.redirectUri);u.searchParams.set("code",r.code);if(r.state)u.searchParams.set("state",r.state);window.location.assign(u.toString());}catch(e){setError(e instanceof Error?e.message:"Unable to approve access.");setBusy(false)}};if(loading)return <div className="recognized-web"><div className="recognized-loading">Loading authorization…</div></div>;return <div className="recognized-web"><main className="recognized-password" style={{maxWidth:520}}><img className="recognized-logo" src={ReDomLogoSvg} alt="ReDom"/><h1>Connect ReDom to ChatGPT</h1>{request?<><p>ChatGPT is requesting read-only access to your ReDom account.</p><ul style={{textAlign:"left",lineHeight:1.7}}><li>Account and profile information</li><li>Payment and transaction information</li><li>Login history and recognized devices</li><li>Account security status and location information</li></ul><p><b>Read only.</b> ChatGPT cannot change your ReDom account, payments, security settings, or credentials.</p><button type="button" className="recognized-login" disabled={busy} onClick={()=>void approve()}>{busy?"Connecting…":"Allow read-only access"}</button><button type="button" className="recognized-forgot" onClick={()=>window.history.back()}>Cancel</button>{error?<div className="recognized-error" role="alert">{error}</div>:null}</>:<div className="recognized-error" role="alert">{error||"Authorization request unavailable."}</div>}</main></div>;}

export default function App(){const[page,setPage]=useState<Page>(()=>{const routed=routePage();return routed==="policy"||routed==="support-case"||(routed==="login-entry"&&!oauthRequestId())?routed:oauthRequestId()&&routed==="login-entry"?"login":"startup"}),[network,setNetwork]=useState<NetworkProviderResponse|null>(null),[user,setUser]=useState<User|null>(null),[ready,setReady]=useState(false);const[loginEntryBusy,setLoginEntryBusy]=useState(false);const enterLogin=async()=>{if(loginEntryBusy)return;setLoginEntryBusy(true);try{await ensureWebDevice();const accounts=await getRecognizedWebAccounts();if(accounts.length){setPage("recognized-accounts");window.history.pushState({}, "", oauthRequestId()?`/app/login?oauth_request=${encodeURIComponent(oauthRequestId()!)}`:"/app/login");}else{setPage("login");window.history.pushState({}, "", oauthRequestId()?`/app/login?oauth_request=${encodeURIComponent(oauthRequestId()!)}`:"/app/login");}}catch{setPage("login");window.history.pushState({}, "", oauthRequestId()?`/app/login?oauth_request=${encodeURIComponent(oauthRequestId()!)}`:"/app/login");}finally{setLoginEntryBusy(false)}};const go=(p:Page)=>{const path=pagePath(p);if(path)window.history.pushState({}, "", path);setPage(p);window.scrollTo({top:0,behavior:"smooth"});};useEffect(()=>{const s=getSession();if(s){api<any>("/profile").then(r=>{if(r.profile){setUser({...r.profile,id:r.profile.userId});if(oauthRequestId())setPage("oauth-consent")}}).catch(()=>clearSession()).finally(()=>setReady(true))}else setReady(true)},[]);
useEffect(()=>{if(ready&&page==="login-entry")void enterLogin()},[ready,page]);if(!ready)return <div className="boot"><SvgAsset src={ReDomLogoSvg} className="redom-logo-svg" /><b>ReDom</b><span>Loading…</span></div>;if(page==="startup")return <Startup done={()=>{if(user){go("home");}else{void enterLogin();}}} setNetwork={setNetwork}/>;if(page==="oauth-consent")return <OAuthConsent go={go}/>;if(page==="login-entry")return <div className="recognized-web"><div className="recognized-loading">Loading login…</div></div>;if(page==="policy")return <PolicyPage/>;if(page==="support-case")return user?<SupportCasePage go={go}/>:<Login go={go} network={network} setUser={setUser}/>;if(page==="recognized-accounts")return <RecognizedAccounts go={go} network={network}/>;if(page==="recognized-password")return <RecognizedPassword go={go} setUser={setUser}/>;if(page==="manage-profiles")return <ManageProfiles go={go}/>;if(page==="profile-detail")return <ProfileDetail go={go}/>;if(page==="web-parity"||page==="home")return user?<WebParityRouter user={user} onLogout={async()=>{try{await api("/auth/logout",{method:"POST"})}catch{}clearSession();setUser(null);window.history.pushState({}, "", "/");setPage("startup");}}/>:<Login go={go} network={network} setUser={setUser}/>;if(page==="login")return <Login go={go} network={network} setUser={setUser}/>;if(page==="find-account")return <FindAccount go={go}/>;if(page==="reset-code")return <ResetCode go={go}/>;if(page==="reset-password")return <ResetPassword go={go}/>;if(page==="device-verify")return <DeviceVerify go={go} setUser={setUser}/>;if(page==="two-factor")return <TwoFactor go={go} setUser={setUser}/>;const f=readReg();if(page==="register-welcome")return <RegisterWelcome go={go}/>;if(!f)return <Login go={go} network={network} setUser={setUser}/>;if(page==="register-identity")return <RegIdentity flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-birthday")return <RegBirthday flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-gender")return <RegGender flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-phone")return <RegPhone flow={f!} go={go} setFlow={writeReg} network={network}/>;if(page==="register-email")return <RegEmail flow={f!} go={go} setFlow={writeReg} network={network}/>;if(page==="register-password")return <RegPassword flow={f!} go={go} setFlow={writeReg}/>;if(page==="register-review")return <RegReview flow={f!} go={go} network={network}/>;if(page==="register-verify")return <RegVerify go={go}/>;if(page==="customizing")return <Customizing go={go} setUser={setUser}/>;return user?<Home user={user} setUser={setUser}/>:<Login go={go} network={network} setUser={setUser}/>}
